import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as a}from"./chunks/Tags.BJ536pW3.js";import{c as o,o as r,j as i,G as t,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Secure America Act","description":"","frontmatter":{"legisId":"2026-06-10-secure-america-act","title":"Secure America Act","displayTitle":"Secure America Act","lawNumber":"119-98","billNumber":"S. 2","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ98.xml","publishDate":"2026-06-10T00:00:00-05:00","industries":["immigration","law-enforcement","government-operations"],"agencies":["Department of Homeland Security","U.S. Customs and Border Protection","U.S. Immigration and Customs Enforcement","Homeland Security Investigations"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Secure America Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-10-secure-america-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Secure America Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-10-secure-america-act\\",\\"datePublished\\":\\"2026-06-10T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-10-secure-america-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-06-10-secure-america-act.md","filePath":"congress-bills/2026-06-10-secure-america-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-06-10-secure-america-act.md"},h=Object.assign(d,{setup(c){return(m,e)=>(r(),o("div",null,[e[0]||(e[0]=i("h1",{id:"secure-america-act",tabindex:"-1"},[l("Secure America Act "),i("a",{class:"header-anchor",href:"#secure-america-act","aria-label":'Permalink to "Secure America Act"'},"​")],-1)),t(n),t(a,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Wednesday, June 10, 2026. Public Law 119-98, S. 2.</p><p><strong>Headline:</strong> The law provides nearly $69.6 billion to expand federal border security, immigration enforcement, and related investigations through fiscal year 2029.</p><p><strong>Why it matters:</strong> The funding significantly increases federal personnel, technology, detention and removal operations, drug interdiction, and cooperation with state and local authorities.</p><p><strong>What the law does:</strong></p><ul><li>Provides $22.57 billion to U.S. Customs and Border Protection for staffing, immigration enforcement, screening, surveillance, biometric systems, air and marine operations, and drug interdiction.</li><li>Provides $38.525 billion to U.S. Immigration and Customs Enforcement for staffing, investigations, removals, transportation, facilities, technology, legal support, and other operations.</li><li>Dedicates $108.5 million to child-exploitation investigations, forensic analysis, victim identification and rescue, and related training.</li><li>Requires at least $350 million for enforcement involving specified adults in jurisdictions that do not meet federal cooperation requirements, excluding tribal governments.</li><li>Provides the Department of Homeland Security an additional $5 billion for authorized purposes under the law and existing law.</li><li>Restricts certain spending, including funding for untested surveillance towers and most community releases or alternatives to detention for specified individuals.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Border Patrol agents, immigration officers, investigators, analysts, legal staff, and other Department of Homeland Security personnel.</li><li>Adults subject to immigration detention, monitoring, transportation, arrest, departure, or removal.</li><li>State and local authorities assisting federal immigration enforcement, including jurisdictions that do not meet federal cooperation requirements.</li><li>Children exploited by criminals and personnel involved in identifying and rescuing victims.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Travelers and border communities may encounter expanded screening, surveillance, biometric systems, and enforcement staffing.</li><li>People facing immigration enforcement may see increased detention, monitoring, transportation, and removal capacity.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="title-i-committee-on-homeland-security-and-governmental-affairs" tabindex="-1">TITLE I, COMMITTEE ON HOMELAND SECURITY AND GOVERNMENTAL AFFAIRS <a class="header-anchor" href="#title-i-committee-on-homeland-security-and-governmental-affairs" aria-label="Permalink to &quot;TITLE I, COMMITTEE ON HOMELAND SECURITY AND GOVERNMENTAL AFFAIRS&quot;">​</a></h3><p>This title provides $22.95 billion in additional fiscal year 2026 funding for Customs and Border Protection, Immigration and Customs Enforcement, and other Department of Homeland Security activities, with funds generally available through September 30, 2029. It supports personnel, child-exploitation investigations, border screening and surveillance technology, air and marine capabilities, drug-interdiction efforts, biometric entry and exit systems, and related operations, while limiting specified immigration and customs enforcement uses.</p><p><strong>Key takeaways:</strong></p><ul><li>Customs and Border Protection receives $9.55 billion to hire, pay, train, and equip Border Patrol agents and support personnel for duties other than immigration enforcement and customs functions.</li><li>After October 31, 2028, the Customs and Border Protection personnel funding cannot be used to recruit, hire, or train processing coordinators.</li><li>Immigration and Customs Enforcement receives $7.45 billion for Homeland Security Investigations personnel, mission support, operations, and maintenance outside its immigration and customs enforcement missions.</li><li>Of the Homeland Security Investigations funding, $108.5 million is dedicated to child-exploitation investigators, forensic analysts, victim identification and rescue work, and related training for federal, state, and local personnel.</li><li>Customs and Border Protection receives $3.45 billion for inspection equipment, border surveillance, air and marine response platforms, biometric entry and exit systems, drug-interdiction efforts, and related support, but unaccepted surveillance towers lacking tested autonomous capabilities cannot be funded.</li><li>The Department of Homeland Security receives an additional $2.5 billion for the purposes covered by this title.</li></ul><h3 id="title-ii-committee-on-the-judiciary" tabindex="-1">TITLE II, COMMITTEE ON THE JUDICIARY <a class="header-anchor" href="#title-ii-committee-on-the-judiciary" aria-label="Permalink to &quot;TITLE II, COMMITTEE ON THE JUDICIARY&quot;">​</a></h3><p>This title provides $46.595 billion in additional fiscal year 2026 funding for federal immigration enforcement, available through September 30, 2029. It funds Customs and Border Protection personnel and operations, Immigration and Customs Enforcement staffing and removal activities, and additional Department of Homeland Security purposes authorized by this title and specified existing law.</p><p><strong>Key takeaways:</strong></p><ul><li>Customs and Border Protection receives $13.02 billion to hire, pay, train, and equip agents and support staff and to fund immigration enforcement operations and maintenance.</li><li>Immigration and Customs Enforcement receives $31.075 billion for personnel, transportation for departures and removals, information technology, facilities, vehicles, legal staff, mission support, and enforcement operations.</li><li>The ICE funding supports expanded agreements that allow state and local authorities to assist with federal immigration enforcement.</li><li>At least $350 million must support detainers, custody transfers, monitoring, transportation, and arrests involving specified adults in jurisdictions that do not meet federal cooperation requirements, while tribal governments are excluded from that category.</li><li>The specified $350 million generally may not be used to release covered individuals into the community, place them in alternatives to detention, or facilitate their release, except when existing law requires it.</li><li>The Department of Homeland Security receives an additional $2.5 billion for purposes authorized by this title and specified provisions of existing law.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ98.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ98.xml</a></p>',19))]))}});export{g as __pageData,h as default};
